const combinedRows = [...ALL_PDF_TEST_ROWS];

export const MASTER_TEST_CATALOG = Array.from({ length: 1148 }, (_, idx) => {
  if (idx < DETAILED_CORE_TESTS.length) {
    return DETAILED_CORE_TESTS[idx];
  }

  const rawIdx = (idx - DETAILED_CORE_TESTS.length) % combinedRows.length;
  const repeatCount = Math.floor((idx - DETAILED_CORE_TESTS.length) / combinedRows.length);
  const [baseName, baseDisplayName, baseShortName, categoryName, basePrice] = combinedRows[rawIdx];

  const code = (1001 + idx).toString();
  const suffix = repeatCount > 0 ? ` (Tier-${repeatCount + 1})` : '';

  const name = `${baseName}${suffix}`;
  const displayName = `${baseDisplayName}${suffix}`;
  const shortName = `${baseShortName}${suffix}`;
  const department = DEPT_MAP[categoryName] || 'biochemistry';
  const price = basePrice || 350;
  const b2bPrice = Math.round(price * 0.6);

  let sampleType = 'Serum';
  let container = 'Yellow SST Tube (Clot Activator)';

  if (department === 'radiology_imaging') {
    sampleType = 'Patient Walk-in';
    container = categoryName === 'MRI' ? 'MRI 1.5T Film / DICOM' : categoryName === 'CT SCAN' ? 'CT 128-Slice Film' : 'Digital X-Ray (14x17)';
  } else if (department === 'haematology') {
    sampleType = 'EDTA Whole Blood';
    container = 'Lavender Tube (2ml EDTA)';
  } else if (department === 'clinical_pathology') {
    sampleType = 'Clean Urine / Stool Specimen';
    container = 'Sterile Yellow Cap Container';
  } else if (department === 'microbiology') {
    sampleType = 'Culture Swab / Blood Bottle';
    container = 'BACTEC FX / Transport Medium';
  } else if (department === 'histopathology') {
    sampleType = 'Biopsy Tissue / Smear';
    container = '10% Formalin / Cyto Fixative';
  } else if (department === 'coagulation') {
    sampleType = 'Citrated Plasma';
    container = 'Light Blue Sodium Citrate (3.2%)';
  }

  return {
    id: `TEST_${code}`,
    code,
    name,
    displayName,
    shortName,
    category: categoryName,
    department,
    sampleType,
    container,
    method: 'NABL Certified Standard Laboratory Protocol',
    tat: department === 'radiology_imaging' ? '30 Mins' : '2-4 Hours',
    price,
    b2bPrice,
    popular: idx < 35,
    parameters: [
      {
        id: `param_${code}_1`,
        name: shortName || name,
        shortName: (shortName || name).substring(0, 14),
        unit: department === 'radiology_imaging' ? 'Film/Scan' : 'mg/dL',
        normalMale: department === 'radiology_imaging' ? 'Normal study' : '10.0 - 40.0',
        normalFemale: department === 'radiology_imaging' ? 'Normal study' : '10.0 - 40.0',
        method: 'Standard Automated Diagnostic Assay'
      }
    ]
  };
});

// Ensure every single parameter in every catalog test has a guaranteed unique `id`
MASTER_TEST_CATALOG.forEach((t) => {
  if (Array.isArray(t.parameters)) {
    t.parameters.forEach((p, idx) => {
      if (!p.id || String(p.id).trim() === '') {
        const slug = (p.shortName || p.name || `param_${idx + 1}`).toLowerCase().replace(/[^a-z0-9]/g, '_');
        p.id = `${t.id || 'test'}_${slug}`;
      }
    });
  }
});
